create extension if not exists pgcrypto;
create type public.staff_role as enum ('administrator','adoption_coordinator','animal_care','content_editor','store_manager','read_only_volunteer');
create type public.cat_status as enum ('available','pending','adopted','medical_hold','foster_only');
create type public.application_status as enum ('Submitted','Under review','Awaiting information','Reference check','Meet-and-greet scheduled','Approved','Declined','Withdrawn','Completed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,display_name text,role public.staff_role not null default 'read_only_volunteer',is_active boolean not null default true);
create table public.cats(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,birth_date date,age_group text not null,sex text not null,breed text not null,color text,status public.cat_status not null default 'available',summary text not null default '',personality text not null default '',story text not null default '',compatibility jsonb not null default '{}',special_needs text not null default '',adoption_fee numeric(8,2) not null default 0,foster_region text,public_medical text not null default '',featured boolean not null default false,archived_at timestamptz);
create table public.cat_photos(id uuid primary key default gen_random_uuid(),cat_id uuid not null references public.cats on delete cascade,path text not null,alt_text text not null,sort_order int not null default 0);
create table public.cat_relationships(id uuid primary key default gen_random_uuid(),cat_id uuid not null references public.cats on delete cascade,related_cat_id uuid not null references public.cats on delete cascade,relationship text not null);
create table public.animal_notes(id uuid primary key default gen_random_uuid(),cat_id uuid not null references public.cats on delete cascade,kind text not null,note text not null,created_by uuid references public.profiles,created_at timestamptz not null default now());
create table public.adoption_applications(id uuid primary key default gen_random_uuid(),reference text unique not null,cat_id uuid references public.cats,email text not null,applicant_name text not null,phone text not null,address jsonb not null,housing jsonb not null,household jsonb not null,pets jsonb not null,veterinarian jsonb not null,lifestyle text not null,answers jsonb not null default '{}',consent_at timestamptz not null,digital_signature text not null,status public.application_status not null default 'Submitted',archived_at timestamptz,created_at timestamptz not null default now());
create table public.application_status_history(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.adoption_applications on delete cascade,from_status public.application_status,to_status public.application_status not null,changed_by uuid references public.profiles,created_at timestamptz not null default now());
create table public.application_notes(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.adoption_applications on delete cascade,note text not null,created_by uuid references public.profiles,created_at timestamptz not null default now());
create table public.content_entries(id uuid primary key default gen_random_uuid(),key text unique not null,kind text not null,title text,fields jsonb not null default '{}',status text not null default 'draft');
create table public.posts(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,excerpt text not null,body text not null,hero_image text,related_cat_ids uuid[] not null default '{}',author_id uuid references public.profiles,status text not null default 'draft',featured boolean not null default false,published_at timestamptz);
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,description text not null,date_time timestamptz not null,location text,map_url text,rsvp_url text,featured_image text,status text not null default 'draft');
create table public.donation_campaigns(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,description text not null,fund text not null,goal numeric(12,2),active boolean not null default true,cat_id uuid references public.cats);
create table public.donations(id uuid primary key default gen_random_uuid(),provider_reference text unique,amount numeric(12,2) not null,frequency text not null,fund text not null,cat_id uuid references public.cats,donor_email text not null,donor_name text,anonymous boolean not null default false,status text not null,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null,category text not null,price numeric(10,2) not null,images text[] not null default '{}',active boolean not null default true,featured boolean not null default false,provider_identifier text,shipping_notes text);
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,sku text unique not null,name text not null,options jsonb not null default '{}',inventory int,active boolean not null default true);
create table public.orders(id uuid primary key default gen_random_uuid(),reference text unique not null,customer_email text not null,total numeric(12,2) not null,status text not null,provider_reference text,archived_at timestamptz,created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,product_variant_id uuid references public.product_variants,product_name text not null,quantity int not null,unit_price numeric(10,2) not null);
create table public.community_submissions(id uuid primary key default gen_random_uuid(),kind text not null,name text not null,email text not null,phone text,payload jsonb not null default '{}',status text not null default 'new',archived_at timestamptz,created_at timestamptz not null default now());
create table public.newsletter_subscribers(id uuid primary key default gen_random_uuid(),email text unique not null,status text not null default 'pending');
create table public.audit_log(id bigint generated always as identity primary key,actor_id uuid references public.profiles,action text not null,entity_type text not null,entity_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());

create schema if not exists private;
create function private.has_role(allowed public.staff_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and is_active and role=any(allowed))$$;
revoke all on function private.has_role(public.staff_role[]) from public; grant usage on schema private to authenticated; grant execute on function private.has_role(public.staff_role[]) to authenticated;
do $$declare t text;begin foreach t in array array['profiles','cats','cat_photos','cat_relationships','animal_notes','adoption_applications','application_status_history','application_notes','content_entries','posts','events','donation_campaigns','donations','products','product_variants','orders','order_items','community_submissions','newsletter_subscribers','audit_log'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "public cats" on public.cats for select to anon,authenticated using(archived_at is null);
create policy "public photos" on public.cat_photos for select to anon,authenticated using(exists(select 1 from public.cats where id=cat_id and archived_at is null));
create policy "public posts" on public.posts for select to anon,authenticated using(status='published');
create policy "public events" on public.events for select to anon,authenticated using(status='published');
create policy "public campaigns" on public.donation_campaigns for select to anon,authenticated using(active);
create policy "public products" on public.products for select to anon,authenticated using(active);
create policy "staff profiles" on public.profiles for select to authenticated using(id=(select auth.uid()) or (select private.has_role(array['administrator'::public.staff_role])));
create policy "animal management" on public.cats for all to authenticated using((select private.has_role(array['administrator','adoption_coordinator','animal_care']::public.staff_role[]))) with check((select private.has_role(array['administrator','adoption_coordinator','animal_care']::public.staff_role[])));
create policy "application management" on public.adoption_applications for all to authenticated using((select private.has_role(array['administrator','adoption_coordinator']::public.staff_role[]))) with check((select private.has_role(array['administrator','adoption_coordinator']::public.staff_role[])));
create policy "content management" on public.content_entries for all to authenticated using((select private.has_role(array['administrator','content_editor']::public.staff_role[]))) with check((select private.has_role(array['administrator','content_editor']::public.staff_role[])));
create policy "store management" on public.products for all to authenticated using((select private.has_role(array['administrator','store_manager']::public.staff_role[]))) with check((select private.has_role(array['administrator','store_manager']::public.staff_role[])));
grant select on public.cats,public.cat_photos,public.posts,public.events,public.donation_campaigns,public.products,public.product_variants to anon,authenticated;
grant select on public.profiles to authenticated;
grant select,insert,update on public.cats,public.cat_photos,public.cat_relationships,public.animal_notes,public.adoption_applications,public.application_status_history,public.application_notes,public.content_entries,public.posts,public.events,public.products,public.product_variants,public.orders,public.order_items,public.community_submissions to authenticated;
-- Anonymous PII writes intentionally go through a future rate-limited server function.
